import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringUtils_ESTest_test22 extends StringUtils_ESTest_scaffolding {

    /**
     * Decoding a byte array of two zero bytes as US-ASCII should yield a
     * two-character string, since each zero byte maps to the NUL (�)
     * character.
     */
    @Test(timeout = 4000)
    public void newStringUsAsciiDecodesZeroBytesToNulCharacters() throws Throwable {
        byte[] twoZeroBytes = new byte[2];

        String decoded = StringUtils.newStringUsAscii(twoZeroBytes);

        assertEquals("\\u0000\\u0000", decoded);
    }
}
